export type AspectRatio = '9:16' | '16:9' | '1:1' | '4:5' | '21:9' | 'Custom';

export interface VideoMetadata {
  duration: number;
  video?: {
    codec: string;
    width: number;
    height: number;
    frameRate: number;
    rotation: number;
  };
  audio?: {
    codec: string;
    sampleRate: number;
    channels: number;
  };
}

export interface VideoTransform {
  zoom: number;
  offsetX: number; 
  offsetY: number; 
}

export interface VideoTrack {
  id: string;
  name: string;
  dataUrl: string;
  startTime: number;
  duration: number;
  transform: VideoTransform;
  blob?: Blob;
  metadata?: VideoMetadata;
  metaError?: string;
}

export interface ClipInput {
  blob: Blob;
  startTime: number;
  duration: number;
  transform: VideoTransform;
}

import React, { Component, type ErrorInfo, type ReactNode } from 'react';

interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: ReactNode;
}

interface ErrorBoundaryState {
  error: Error | null;
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = { error: null };

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error('ErrorBoundary caught error:', error, info);
  }

  handleReset = (): void => {
    this.setState({ error: null });
  };

  render(): ReactNode {
    if (this.state.error) {
      if (this.props.fallback) return this.props.fallback;
      return (
        <div className="flex h-screen w-screen items-center justify-center bg-[#0e0e0e] text-white p-8">
          <div className="max-w-md flex flex-col gap-4 text-center">
            <h1 className="text-lg font-semibold text-white">Something went wrong</h1>
            <p className="text-sm text-zinc-400 break-words">
              {this.state.error.message || 'An unexpected error occurred.'}
            </p>
            <div className="flex gap-2 justify-center">
              <button
                onClick={this.handleReset}
                className="px-4 py-2 rounded-xl bg-white text-black text-sm font-medium hover:bg-zinc-200 transition-colors"
              >
                Try again
              </button>
              <button
                onClick={() => window.location.reload()}
                className="px-4 py-2 rounded-xl border border-white/20 text-sm font-medium hover:bg-white/5 transition-colors"
              >
                Reload page
              </button>
            </div>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type FC,
  type ReactNode,
} from 'react';
import { CheckCircle2, AlertCircle, Info, X } from 'lucide-react';

export type ToastVariant = 'success' | 'error' | 'info';

export interface Toast {
  id: string;
  message: string;
  variant: ToastVariant;
}

interface ToastContextValue {
  toast: (message: string, variant?: ToastVariant, durationMs?: number) => string;
  dismiss: (id: string) => void;
}

const ToastContext = createContext<ToastContextValue | null>(null);

const DEFAULT_DURATION_MS = 5_000;

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) {
    throw new Error('useToast must be used within a <ToastProvider>');
  }
  return ctx;
}

function makeToastId(): string {
  return `toast-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

export const ToastProvider: FC<{ children: ReactNode }> = ({ children }) => {
  const [toasts, setToasts] = useState<Toast[]>([]);
  const timersRef = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map());

  const dismiss = useCallback((id: string) => {
    const timer = timersRef.current.get(id);
    if (timer) {
      clearTimeout(timer);
      timersRef.current.delete(id);
    }
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const toast = useCallback(
    (message: string, variant: ToastVariant = 'info', durationMs = DEFAULT_DURATION_MS) => {
      const id = makeToastId();
      setToasts((prev) => [...prev, { id, message, variant }]);
      if (durationMs > 0) {
        const timer = setTimeout(() => dismiss(id), durationMs);
        timersRef.current.set(id, timer);
      }
      return id;
    },
    [dismiss]
  );

  useEffect(() => {
    const timers = timersRef.current;
    return () => {
      timers.forEach((t) => clearTimeout(t));
      timers.clear();
    };
  }, []);

  const value = useMemo<ToastContextValue>(() => ({ toast, dismiss }), [toast, dismiss]);

  return (
    <ToastContext.Provider value={value}>
      {children}
      <ToastViewport toasts={toasts} onDismiss={dismiss} />
    </ToastContext.Provider>
  );
};

const VARIANT_STYLES: Record<ToastVariant, { ring: string; icon: ReactNode }> = {
  success: {
    ring: 'border-emerald-500/30 bg-emerald-500/10',
    icon: <CheckCircle2 size={16} className="text-emerald-400 shrink-0" />,
  },
  error: {
    ring: 'border-red-500/30 bg-red-500/10',
    icon: <AlertCircle size={16} className="text-red-400 shrink-0" />,
  },
  info: {
    ring: 'border-white/15 bg-white/5',
    icon: <Info size={16} className="text-white/70 shrink-0" />,
  },
};

const ToastViewport: FC<{ toasts: Toast[]; onDismiss: (id: string) => void }> = ({
  toasts,
  onDismiss,
}) => {
  if (toasts.length === 0) return null;
  return (
    <div
      role="region"
      className="fixed bottom-4 left-1/2 -translate-x-1/2 z-[1000] flex flex-col gap-2 pointer-events-none w-full max-w-[360px] px-4"
    >
      {toasts.map((t) => {
        const styles = VARIANT_STYLES[t.variant];
        return (
          <div
            key={t.id}
            className={`pointer-events-auto flex items-start gap-3 px-4 py-3 rounded-2xl border backdrop-blur-md text-white shadow-2xl animate-dropdown ${styles.ring}`}
          >
            <div className="pt-0.5">{styles.icon}</div>
            <p className="text-[12px] leading-snug flex-1 break-words">{t.message}</p>
            <button
              type="button"
              onClick={() => onDismiss(t.id)}
              className="text-white/50 hover:text-white transition-colors p-0.5"
            >
              <X size={14} />
            </button>
          </div>
        );
      })}
    </div>
  );
};

import React, {
  useState,
  useRef,
  useEffect,
  useId,
  type FC,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
} from 'react';
import { ChevronDown } from 'lucide-react';

export const SectionLabel: FC<{ children: ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">
      {children}
    </span>
  </div>
);

export const PillButton: FC<{
  icon?: ReactNode;
  children: ReactNode;
  variant?: 'filled' | 'outline' | 'solid';
  onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

export const FieldDropdown: FC<{
  label: string;
  value: string;
  options: string[];
  onChange: (val: string) => void;
  className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState<number>(() =>
    Math.max(0, options.indexOf(value))
  );
  const ref = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const optionRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const listboxId = useId();

  useEffect(() => {
    const listener = (event: PointerEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      setIsOpen(false);
    };
    document.addEventListener('pointerdown', listener);
    return () => document.removeEventListener('pointerdown', listener);
  }, []);

  useEffect(() => {
    const idx = options.indexOf(value);
    if (idx >= 0) setActiveIndex(idx);
  }, [value, options]);

  useEffect(() => {
    if (!isOpen) return;
    const node = optionRefs.current[activeIndex];
    node?.focus();
  }, [isOpen, activeIndex]);

  const commit = (idx: number) => {
    const opt = options[idx];
    if (opt === undefined) return;
    onChange(opt);
    setIsOpen(false);
    triggerRef.current?.focus();
  };

  const handleTriggerKeyDown = (e: ReactKeyboardEvent<HTMLButtonElement>) => {
    if (e.key === 'ArrowDown' || e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowUp') {
      e.preventDefault();
      setIsOpen(true);
    }
  };

  const handleOptionKeyDown = (e: ReactKeyboardEvent<HTMLButtonElement>, idx: number) => {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setActiveIndex((idx + 1) % options.length);
        break;
      case 'ArrowUp':
        e.preventDefault();
        setActiveIndex((idx - 1 + options.length) % options.length);
        break;
      case 'Home':
        e.preventDefault();
        setActiveIndex(0);
        break;
      case 'End':
        e.preventDefault();
        setActiveIndex(options.length - 1);
        break;
      case 'Enter':
      case ' ':
        e.preventDefault();
        commit(idx);
        break;
      case 'Escape':
      case 'Tab':
        if (e.key === 'Escape') e.preventDefault();
        setIsOpen(false);
        if (e.key === 'Escape') triggerRef.current?.focus();
        break;
    }
  };

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button
        ref={triggerRef}
        type="button"
        onClick={() => setIsOpen((o) => !o)}
        onKeyDown={handleTriggerKeyDown}
        aria-haspopup="listbox"
        aria-expanded={isOpen}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none focus-visible:border-white/60 bg-transparent"
      >
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px]">{value}</span>
          <ChevronDown size={16} className={`text-[rgba(218,220,224,0.5)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        </div>
      </button>
      {isOpen && (
        <div
          id={listboxId}
          role="listbox"
          className="absolute z-[100] top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-xl backdrop-blur-md animate-dropdown origin-top"
        >
          <div className="max-h-40 overflow-y-auto dark-scrollbar">
            {options.map((opt, idx) => {
              const selected = value === opt;
              return (
                <button
                  key={opt}
                  ref={(el) => {
                    optionRefs.current[idx] = el;
                  }}
                  id={`${listboxId}-opt-${idx}`}
                  type="button"
                  role="option"
                  aria-selected={selected}
                  tabIndex={-1}
                  className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] focus:bg-[#1a1a1a] focus:outline-none transition-colors ${selected ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                  onClick={() => commit(idx)}
                  onKeyDown={(e) => handleOptionKeyDown(e, idx)}
                  onMouseEnter={() => setActiveIndex(idx)}
                >
                  {opt}
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

import React, {
  useState,
  useRef,
  useEffect,
  useLayoutEffect,
  useCallback,
  useMemo,
  type FC,
  type PointerEvent as ReactPointerEvent,
} from 'react';
import {
  Upload,
  RefreshCcw,
  Maximize,
  Maximize2,
  Minimize2,
  Loader2,
  Download,
  RotateCcw,
  Move,
  Settings2,
  FileVideo,
  Info,
  X,
  Save,
} from 'lucide-react';
import { Flow } from 'flow-sdk';
import { extractMetadata, reencodeVideo } from '../lib/mediabunny';
import { VideoTrack, AspectRatio } from '../types';
import {
  SectionLabel,
  PillButton,
  FieldDropdown,
} from './UI';
import { useToast } from './Toast';

const MAX_DIMENSION = 4096;
const MAX_FILE_SIZE_BYTES = 2 * 1024 * 1024 * 1024; // 2 GB

function makeId(): string {
  return `id-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 11)}`;
}

function formatBytes(bytes: number): string {
  const gb = bytes / (1024 * 1024 * 1024);
  if (gb >= 1) return `${gb.toFixed(1)} GB`;
  const mb = bytes / (1024 * 1024);
  return `${mb.toFixed(0)} MB`;
}

export const VideoEditor: FC = () => {
  const { toast } = useToast();
  const [track, setTrack] = useState<VideoTrack | null>(null);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('9:16');
  const [customWidth, setCustomWidth] = useState<number>(1080);
  const [customHeight, setCustomHeight] = useState<number>(1080);
  const [customWidthInput, setCustomWidthInput] = useState<string>('1080');
  const [customHeightInput, setCustomHeightInput] = useState<string>('1080');
  const [isRendering, setIsRendering] = useState(false);
  const [progress, setProgress] = useState(0);

  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const exportAbortRef = useRef<AbortController | null>(null);

  const [canvasSize, setCanvasSize] = useState({ width: 0, height: 0 });
  useLayoutEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    let rafId = 0;
    let pending: { width: number; height: number } | null = null;
    const flush = () => {
      rafId = 0;
      if (pending) {
        setCanvasSize(pending);
        pending = null;
      }
    };
    const update = () => {
      const r = el.getBoundingClientRect();
      pending = { width: r.width, height: r.height };
      if (!rafId) rafId = requestAnimationFrame(flush);
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => {
      ro.disconnect();
      if (rafId) cancelAnimationFrame(rafId);
    };
  }, []);

  const [stageSize, setStageSize] = useState({ width: 0, height: 0 });
  useLayoutEffect(() => {
    const el = stageRef.current;
    if (!el) return;
    let rafId = 0;
    let pending: { width: number; height: number } | null = null;
    const flush = () => {
      rafId = 0;
      if (pending) {
        setStageSize(pending);
        pending = null;
      }
    };
    const update = () => {
      const r = el.getBoundingClientRect();
      pending = { width: r.width, height: r.height };
      if (!rafId) rafId = requestAnimationFrame(flush);
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => {
      ro.disconnect();
      if (rafId) cancelAnimationFrame(rafId);
    };
  }, []);

  type DragMode = 'drag' | 'resize';
  type Corner = { x: -1 | 1; y: -1 | 1 };
  type SnapTargetX = { value: number; edge: 'left' | 'center' | 'right' };
  type SnapTargetY = { value: number; edge: 'top' | 'center' | 'bottom' };
  type SnapEdges = {
    top: boolean;
    right: boolean;
    bottom: boolean;
    left: boolean;
    centerX: boolean;
    centerY: boolean;
  };
  type DragState = {
    mode: DragMode;
    pointerId: number;
    target: HTMLElement;
    startX: number;
    startY: number;
    startOffX: number;
    startOffY: number;
    startZoom: number;
    videoWidth: number;
    videoHeight: number;
    rectWidth: number;
    rectHeight: number;
    corner: Corner | null;
    snapZooms: number[];
    snapX: SnapTargetX[];
    snapY: SnapTargetY[];
    snappedX: SnapTargetX['edge'] | null;
    snappedY: SnapTargetY['edge'] | null;
  };
  const dragRef = useRef<DragState | null>(null);
  const [interaction, setInteraction] = useState<DragMode | null>(null);
  const [snapEdges, setSnapEdges] = useState<SnapEdges>({
    top: false, right: false, bottom: false, left: false, centerX: false, centerY: false,
  });
  const [isDropTarget, setIsDropTarget] = useState(false);

  const loadFile = useCallback(
    async (file: File) => {
      if (file.type && !file.type.startsWith('video/')) {
        toast(`File format "${file.type}" not supported.`, 'error');
        return;
      }

      if (file.size > MAX_FILE_SIZE_BYTES) {
        toast(`File too large (${formatBytes(file.size)}). Max: 2 GB.`, 'error');
        return;
      }

      let nextDataUrl: string | null = null;
      try {
        const metadata = await extractMetadata(file);
        nextDataUrl = URL.createObjectURL(file);

        const newTrack: VideoTrack = {
          id: makeId(),
          name: file.name || 'Video',
          dataUrl: nextDataUrl,
          startTime: 0,
          duration: metadata.duration,
          transform: { zoom: 1, offsetX: 0, offsetY: 0 },
          blob: file,
          metadata,
        };

        setTrack((prev) => {
          if (prev?.dataUrl) URL.revokeObjectURL(prev.dataUrl);
          return newTrack;
        });
      } catch (err) {
        console.error('Video load failed:', err);
        if (nextDataUrl) URL.revokeObjectURL(nextDataUrl);
        toast('Could not process this video. Please try another file.', 'error');
      }
    },
    [toast]
  );

  const handleSelectVideo = async () => {
    try {
      const media = await Flow.media.select({ filter: 'video' });
      if (media) {
        const bytes = Uint8Array.from(atob(media.base64), (c) => c.charCodeAt(0));
        const file = new File([bytes], media.name, { type: media.mimeType });
        void loadFile(file);
      }
    } catch (err) {
      console.error('Flow selection error:', err);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    if (track) return;
    if (!Array.from(e.dataTransfer.types).includes('Files')) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
    setIsDropTarget(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    if (e.currentTarget === e.target) setIsDropTarget(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    if (track) return;
    e.preventDefault();
    setIsDropTarget(false);
    const file = e.dataTransfer.files?.[0];
    if (file) void loadFile(file);
  };

  useEffect(() => {
    return () => {
      setTrack((prev) => {
        if (prev?.dataUrl) URL.revokeObjectURL(prev.dataUrl);
        return prev;
      });
    };
  }, []);

  const updateTransform = useCallback((updates: Partial<VideoTrack['transform']>) => {
    setTrack(prev => {
      if (!prev) return null;
      return {
        ...prev,
        transform: { ...prev.transform, ...updates }
      };
    });
  }, []);

  const resetTransform = () => updateTransform({ zoom: 1, offsetX: 0, offsetY: 0 });
  const applyFit = () => updateTransform({ zoom: 1, offsetX: 0, offsetY: 0 });
  const applyFill = () => {
    const Wc = canvasSize.width || 1;
    const Hc = canvasSize.height || 1;
    const canvasAspect = Wc / Hc;
    const fillZoom = videoAspect > canvasAspect ? videoAspect / canvasAspect : canvasAspect / videoAspect;
    updateTransform({ zoom: fillZoom, offsetX: 0, offsetY: 0 });
  };

  const videoAspect = track?.metadata?.video ? track.metadata.video.width / track.metadata.video.height : 1;

  const wrapBase = useMemo(() => {
    const Wc = canvasSize.width || 1;
    const Hc = canvasSize.height || 1;
    if (!track) return { w: Wc, h: Hc };
    return videoAspect > (Wc / Hc) ? { w: Wc, h: Wc / videoAspect } : { w: Hc * videoAspect, h: Hc };
  }, [canvasSize, track, videoAspect]);

  const handlePointerDown = (e: ReactPointerEvent<HTMLElement>, mode: DragMode, corner: Corner | null = null) => {
    if (!track || !containerRef.current) return;
    if (e.button !== 0 && e.pointerType === 'mouse') return;
    e.preventDefault();
    e.stopPropagation();

    const rect = containerRef.current.getBoundingClientRect();
    const targetEl = e.currentTarget;
    targetEl.setPointerCapture(e.pointerId);

    const canvasAspect = rect.width / rect.height;
    const fillZoom = videoAspect > canvasAspect ? videoAspect / canvasAspect : canvasAspect / videoAspect;

    const snapZooms = [1];
    if (Math.abs(fillZoom - 1) > 0.01) snapZooms.push(fillZoom);

    const Wwrap = wrapBase.w || rect.width;
    const Hwrap = wrapBase.h || rect.height;
    const z = track.transform.zoom;

    const snapX: SnapTargetX[] = [
      { value: ((Wwrap * z) / 2 - rect.width / 2) / Wwrap * 100, edge: 'left' },
      { value: 0, edge: 'center' },
      { value: (rect.width / 2 - (Wwrap * z) / 2) / Wwrap * 100, edge: 'right' },
    ];
    const snapY: SnapTargetY[] = [
      { value: ((Hwrap * z) / 2 - rect.height / 2) / Hwrap * 100, edge: 'top' },
      { value: 0, edge: 'center' },
      { value: (rect.height / 2 - (Hwrap * z) / 2) / Hwrap * 100, edge: 'bottom' },
    ];

    dragRef.current = {
      mode, pointerId: e.pointerId, target: targetEl,
      startX: e.clientX, startY: e.clientY,
      startOffX: track.transform.offsetX, startOffY: track.transform.offsetY,
      startZoom: track.transform.zoom, 
      videoWidth: Wwrap, videoHeight: Hwrap,
      rectWidth: rect.width, rectHeight: rect.height,
      corner, snapZooms, snapX, snapY, snappedX: null, snappedY: null,
    };
    setInteraction(mode);
  };

  const handlePointerMove = (e: ReactPointerEvent<HTMLElement>) => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== e.pointerId) return;

    const dx = e.clientX - drag.startX;
    const dy = e.clientY - drag.startY;

    if (drag.mode === 'drag') {
      // To follow the cursor 1:1, we must account for the fact that transform: translate(X%, Y%) scale(Z)
      // translates by a percentage of the unscaled width, and then scales that visual distance by Z.
      // Visual distance = (Δ% / 100) * BaseWidth * Zoom
      // So Δ% = (dx / (BaseWidth * Zoom)) * 100
      const rawX = drag.startOffX + (dx / (drag.videoWidth * drag.startZoom)) * 100;
      const rawY = drag.startOffY + (dy / (drag.videoHeight * drag.startZoom)) * 100;

      let nextX = rawX;
      let nextY = rawY;
      let snappedXEdge: SnapTargetX['edge'] | null = null;
      let snappedYEdge: SnapTargetY['edge'] | null = null;

      if (!e.shiftKey) {
        const threshold = 3.0;
        let bestX: SnapTargetX | null = null;
        let minX = Infinity;
        for (const t of drag.snapX) {
          const d = Math.abs(rawX - t.value);
          if (d < minX) { minX = d; bestX = t; }
        }
        if (bestX && minX <= threshold) { nextX = bestX.value; snappedXEdge = bestX.edge; }

        let bestY: SnapTargetY | null = null;
        let minY = Infinity;
        for (const t of drag.snapY) {
          const d = Math.abs(rawY - t.value);
          if (d < minY) { minY = d; bestY = t; }
        }
        if (bestY && minY <= threshold) { nextY = bestY.value; snappedYEdge = bestY.edge; }
      }

      drag.snappedX = snappedXEdge;
      drag.snappedY = snappedYEdge;
      setSnapEdges({
        left: snappedXEdge === 'left', right: snappedXEdge === 'right', centerX: snappedXEdge === 'center',
        top: snappedYEdge === 'top', bottom: snappedYEdge === 'bottom', centerY: snappedYEdge === 'center',
      });

      updateTransform({ offsetX: Math.max(-500, Math.min(500, nextX)), offsetY: Math.max(-500, Math.min(500, nextY)) });
    } else {
      const corner = drag.corner ?? { x: 1, y: 1 };
      const projected = (dx * corner.x + dy * corner.y) / Math.SQRT2;
      let nextZoom = Math.max(0.1, Math.min(20, drag.startZoom + projected / 200));

      if (!e.shiftKey) {
        for (const z of drag.snapZooms) {
          if (Math.abs(nextZoom - z) <= 0.03) { nextZoom = z; break; }
        }
      }
      updateTransform({ zoom: nextZoom });
    }
  };

  const endDrag = (e: ReactPointerEvent<HTMLElement>) => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== e.pointerId) return;
    try { drag.target.releasePointerCapture(drag.pointerId); } catch { }
    dragRef.current = null;
    setInteraction(null);
    setSnapEdges({ top: false, right: false, bottom: false, left: false, centerX: false, centerY: false });
  };

  const handleRender = async () => {
    if (!track) return;
    exportAbortRef.current?.abort();
    const controller = new AbortController();
    exportAbortRef.current = controller;

    setIsRendering(true);
    setProgress(0);

    let simulatedInterval: ReturnType<typeof setInterval> | null = null;

    try {
      const resMap: Record<string, [number, number]> = {
        '9:16': [1080, 1920], '16:9': [1920, 1080],
        '1:1': [1080, 1080], '4:5': [1080, 1350],
        '21:9': [2560, 1080]
      };
      const [w, h] = aspectRatio === 'Custom' ? [customWidth, customHeight] : resMap[aspectRatio];
      const videoName = `Resized_${w}x${h}_${track.name.replace(/\.[^/.]+$/, "")}.mp4`;

      const blob = await reencodeVideo(
        { blob: track.blob!, startTime: track.startTime, duration: track.duration, transform: track.transform },
        w, h, (p) => setProgress(p * 0.8),
        { metadata: track.metadata, signal: controller.signal }
      );

      if (controller.signal.aborted) return;

      setProgress(0.81); 

      const base64 = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => {
          const res = (reader.result as string).split(',')[1];
          if (res) resolve(res);
          else reject(new Error('Failed to extract base64 data'));
        };
        reader.onerror = () => reject(new Error('Failed to read video buffer'));
        reader.readAsDataURL(blob);
      });

      setProgress(0.90);
      let simulatedProgress = 0.90;
      simulatedInterval = setInterval(() => {
        const remaining = 0.99 - simulatedProgress;
        simulatedProgress += remaining * 0.05;
        setProgress(simulatedProgress);
      }, 300);

      await Flow.save({
        base64,
        mimeType: 'video/mp4',
        name: videoName
      });

      if (simulatedInterval) clearInterval(simulatedInterval);
      setProgress(1);
    } catch (err) {
      if (simulatedInterval) clearInterval(simulatedInterval);
