            {track ? (
              <div className="w-full h-full relative flex items-center justify-center">
                {snapEdges.top && <div className="absolute top-0 left-0 right-0 h-px bg-white pointer-events-none z-40 shadow-[0_0_6px_rgba(255,255,255,0.8)]" />}
                {snapEdges.bottom && <div className="absolute bottom-0 left-0 right-0 h-px bg-white pointer-events-none z-40 shadow-[0_0_6px_rgba(255,255,255,0.8)]" />}
                {snapEdges.left && <div className="absolute top-0 bottom-0 left-0 w-px bg-white pointer-events-none z-40 shadow-[0_0_6px_rgba(255,255,255,0.8)]" />}
                {snapEdges.right && <div className="absolute top-0 bottom-0 right-0 w-px bg-white pointer-events-none z-40 shadow-[0_0_6px_rgba(255,255,255,0.8)]" />}
                {snapEdges.centerX && <div className="absolute top-0 bottom-0 left-1/2 w-px -translate-x-1/2 bg-cyan-400 pointer-events-none z-40 shadow-[0_0_6px_rgba(34,211,238,0.8)]" />}
