                <div className="relative pointer-events-none" style={{ width: wrapBase.w, height: wrapBase.h, transform: `translate(${track.transform.offsetX}%, ${track.transform.offsetY}%) scale(${track.transform.zoom})`, transformOrigin: 'center', transition: interaction ? 'none' : 'transform 75ms ease-out' }}>
                  <video ref={videoRef} src={track.dataUrl} className="w-full h-full pointer-events-none" autoPlay muted loop playsInline />
                </div>
                <div
                  className={`absolute group touch-none ${interaction ? 'opacity-100' : 'opacity-0 hover:opacity-100'}`}
                  style={{ left: contentRect.left, top: contentRect.top, width: contentRect.width, height: contentRect.height, zIndex: 20, transition: interaction ? 'none' : 'left 300ms ease-out, top 300ms ease-out, width 300ms ease-out, height 300ms ease-out' }}
                >
                  <div className="absolute inset-0 cursor-move" onPointerDown={(e) => handlePointerDown(e, 'drag')} onPointerMove={handlePointerMove} onPointerUp={endDrag} onPointerCancel={endDrag}>
                    <div className="absolute inset-0 border-2 border-white/30 pointer-events-none group-hover:border-white/50" />
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-3 h-3 border-2 border-white bg-black rounded-full pointer-events-none shadow-lg z-20" />
