              <button onClick={resetTransform} disabled={!track} className="flex flex-col items-center justify-center gap-1.5 py-3 rounded-2xl border border-white/5 bg-white/[0.02] hover:bg-white/[0.05] text-white/70 hover:text-white disabled:opacity-40 transition-colors"><RotateCcw size={14} /><span className="text-[10px] font-medium uppercase tracking-wider">Reset</span></button>
            </div>
          </div>
        </div>

        <div className="p-6 border-t border-white/5 bg-[#0e0e0e] flex flex-col gap-3">
          {isRendering && (
            <div className="flex flex-col gap-2">
              <div className="flex items-center justify-between text-[10px] font-bold text-white/40 uppercase tracking-widest px-1">
                <span>{progress < 0.8 ? 'Rendering' : progress < 0.9 ? 'Processing Buffer' : 'Syncing to Gallery'}</span>
                <span>{Math.round(progress * 100)}%</span>
              </div>
              <div className="flex items-center gap-3">
                <div className="flex-1 bg-white/5 rounded-full h-1 overflow-hidden">
                  <div className="bg-white h-full transition-all duration-300 ease-out shadow-[0_0_8px_rgba(255,255,255,0.4)]" style={{ width: `${progress * 100}%` }} />
                </div>
                <button type="button" onClick={handleCancelExport} className="shrink-0 p-1.5 rounded-lg text-zinc-400 hover:text-white hover:bg-white/10 transition-colors"><X size={14} /></button>
              </div>
            </div>
          )}
          <PillButton variant="solid" icon={isRendering ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />} onClick={handleRender} disabled={isRendering || !track}>
            {isRendering ? `Processing...` : 'Export Video'}
          </PillButton>
        </div>
      </div>
    </div>
  );
};

import {
  Input,
  Output,
  Conversion,
  BlobSource,
  BufferTarget,
  Mp4OutputFormat,
  ALL_FORMATS,
} from 'mediabunny';
import { VideoMetadata, ClipInput } from '../types';

// Constants for high-quality export
const AUDIO_BITRATE = 128_000;   // 128 kbps
const DEFAULT_FRAME_RATE = 30;

/** Round dimension down to even integer for H.264 compatibility. */
function toEvenDimension(value: number): number {
  return Math.max(2, Math.floor(value / 2) * 2);
}

/**
 * Extracts metadata from a video file, correctly normalizing 
 * width and height based on rotation metadata.
 */
export async function extractMetadata(blob: Blob): Promise<VideoMetadata> {
  const input = new Input({
    formats: ALL_FORMATS,
    source: new BlobSource(blob),
  });

  try {
    const duration = await input.computeDuration();
    const videoTracks = await input.getVideoTracks();
    const audioTracks = await input.getAudioTracks();

    let video: VideoMetadata['video'];
    if (videoTracks.length > 0) {
      const track = videoTracks[0];
      let frameRate = DEFAULT_FRAME_RATE;
      try {
        const stats = await track.computePacketStats();
        frameRate = stats.averagePacketRate || DEFAULT_FRAME_RATE;
      } catch (e) {
        console.warn('Metadata extraction: packet stats failed, using 30fps default');
      }

      // Crucial: Swap dimensions if video is rotated vertically (90 or 270 degrees)
      // This ensures the UI preview and export math use the visual aspect ratio.
      const rotation = track.rotation || 0;
      const isVertical = rotation === 90 || rotation === 270;

      video = {
        codec: track.codec || 'unknown',
        width: isVertical ? track.displayHeight : track.displayWidth,
        height: isVertical ? track.displayWidth : track.displayHeight,
        frameRate,
        rotation,
      };
    }

    let audio: VideoMetadata['audio'];
    if (audioTracks.length > 0) {
      const track = audioTracks[0];
      audio = {
        codec: track.codec || 'unknown',
        sampleRate: track.sampleRate,
        channels: track.numberOfChannels,
      };
    }

    return { duration, video, audio };
  } finally {
    input.dispose();
  }
}

export interface ReencodeOptions {
  metadata?: VideoMetadata;
  signal?: AbortSignal;
}

/**
 * Re-encodes a video clip with custom reframing transformations.
 * Uses visual dimensions for all math to ensure parity with the UI preview.
 */
export async function reencodeVideo(
  clip: ClipInput,
  targetWidth: number,
  targetHeight: number,
  onProgress: (progress: number) => void,
  options: ReencodeOptions = {}
): Promise<Blob> {
  // Ensure we have normalized metadata (with rotation applied to width/height)
  const meta = options.metadata ?? (await extractMetadata(clip.blob));
  if (!meta.video) throw new Error('Source video track missing');

  const evenWidth = toEvenDimension(targetWidth);
  const evenHeight = toEvenDimension(targetHeight);

  // A3: Adaptive Bitrate Computation
  // Bits Per Pixel (BPP) 0.1 is visually transparent for high-quality H.264
  const finalFrameRate = meta.video.frameRate || DEFAULT_FRAME_RATE;
  const BPP = 0.1;
  const computedBitrate = Math.round(evenWidth * evenHeight * finalFrameRate * BPP);
  // Clamp between 4 Mbps (low end floor) and 32 Mbps (high end ceiling)
  const VIDEO_BITRATE = Math.max(4_000_000, Math.min(32_000_000, computedBitrate));

  const input = new Input({
    formats: ALL_FORMATS,
    source: new BlobSource(clip.blob),
  });

  const output = new Output({
    format: new Mp4OutputFormat({ fastStart: 'in-memory' }),
    target: new BufferTarget(),
  });

  let ctx: OffscreenCanvasRenderingContext2D | null = null;

  const conversion = await Conversion.init({
    input,
    output,
    startTime: clip.startTime,
    duration: clip.duration,
    video: {
      // A2: Native resolution decode. 
      // Omit width/height/fit here so Internal CanvasSink decodes at native size.
      // Use processedWidth/processedHeight to signal the output size of our process callback to the encoder.
      processedWidth: evenWidth,
      processedHeight: evenHeight,
      frameRate: finalFrameRate,
      codec: 'avc',
      bitrate: VIDEO_BITRATE,
      process: (sample) => {
        if (!ctx) {
          const canvas = new OffscreenCanvas(evenWidth, evenHeight);
          // A1: High-quality canvas resampling
          ctx = canvas.getContext('2d', { alpha: false })!;
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
        }

        // 1. Draw Background (Clear/Letterbox)
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, evenWidth, evenHeight);

        // 2. Reframing Math
        const vW = meta.video!.width;
        const vH = meta.video!.height;
        const videoAspect = vW / vH;
        const canvasAspect = evenWidth / evenHeight;

        const baseW = videoAspect > canvasAspect ? evenWidth : evenHeight * videoAspect;
        const baseH = videoAspect > canvasAspect ? evenWidth / videoAspect : evenHeight;

        const zoom = clip.transform.zoom;
        const offX = (clip.transform.offsetX / 100) * baseW;
        const offY = (clip.transform.offsetY / 100) * baseH;

        const drawW = baseW * zoom;
        const drawH = baseH * zoom;

        // 3. Composite Sample
        ctx.save();
        ctx.translate(evenWidth / 2 + offX, evenHeight / 2 + offY);
        // sample.draw is zero-copy and respects our high-quality smoothing settings
        sample.draw(ctx, -drawW / 2, -drawH / 2, drawW, drawH);
        ctx.restore();

        return ctx.canvas;
      }
    },
    audio: meta.audio ? {
      codec: 'aac',
      bitrate: AUDIO_BITRATE,
    } : undefined
  });

  if (!conversion.isValid) {
    throw new Error(`Invalid conversion config: ${JSON.stringify(conversion.discardedTracks)}`);
  }

  // A5: More accurate progress reporting
  // We'll report progress up to 99% during execute, saving 1% for the final buffer finalization
  conversion.onProgress = (p: number) => onProgress(p * 0.99);

  if (options.signal) {
    options.signal.addEventListener('abort', () => conversion.cancel(), { once: true });
  }

  try {
    await conversion.execute();
    // A5: Final completion signal after the tail drain (execute is fully finished)
    onProgress(1);
  } catch (err) {
    if (options.signal?.aborted) throw new DOMException('Export cancelled', 'AbortError');
    throw err;
  } finally {
    input.dispose();
  }

  const buffer = (output.target as BufferTarget).buffer;
  if (!buffer) throw new Error('No output buffer produced');

  return new Blob([buffer], { type: 'video/mp4' });
}

